command:
let hero = game.user.character;

if (!hero) {
  const controlled = canvas.tokens.controlled;
  hero = controlled.find(t => t.actor?.effects.some(fx => fx.name.toUpperCase() === "RAGE"))?.actor;
}

if (!hero) {
  ui.notifications.warn(`No valid Hero found for "Barbarian Rage".`);
}
else {
  let berserk = hero.effects.find(fx => fx.name.toUpperCase() === "BERSERK");
  let rage = hero.effects.find(fx => fx.name.toUpperCase() === "RAGE");
  let murder = hero.effects.find(fx => fx.name.toUpperCase() === "MURDER MODE");

  if (!berserk) {
    // Toggle on the system status effect (forces active: true)
    await hero.toggleStatusEffect("berserk", { active: true });

    // Activate Rage and Murder (disabled: false)
    if (rage) await rage.update({ disabled: false });
    if (murder) await murder.update({ disabled: false });

    ui.notifications.info(`${hero.name} flies into a Barbarian Rage!`);
  }
  else {
    // Toggle off the system status effect (forces active: false)
    await hero.toggleStatusEffect("berserk", { active: false });

    // Deactivate Rage and Murder (disabled: true)
    if (rage) await rage.update({ disabled: true });
    if (murder) await murder.update({ disabled: true });
  }
}
